import { readFile } from 'node:fs/promises';
import path from 'node:path';
import type { Page } from '@playwright/test';

/** The WordPress-rendered immersive story (regenerated by the WordPress E2E suite). */
export const article = '/2026/08/20/news/weekly-wildcat-fixture-story/';
/** Everything outside this origin is served by the test, never the live network. */
export const externalRequests = [
  'https://datawrapper.dwcdn.net/',
  'https://flo.uri.sh/',
  'https://www.openstreetmap.org/',
  'https://www.google.com/maps/embed'
];

const mediaTypes: Record<string, string> = { svg: 'image/svg+xml', mp4: 'video/mp4', pdf: 'application/pdf', wav: 'audio/wav', vtt: 'text/vtt' };

/** Serves test media and controlled provider documents; returns every provider URL requested. */
export async function routeStoryFixtures(page: Page): Promise<string[]> {
  const requested: string[] = [];
  await page.route('**/test-assets/**', async (route) => {
    const name = new URL(route.request().url()).pathname.split('/').pop()!;
    await route.fulfill({
      body: await readFile(path.resolve(__dirname, '../../../../tests/fixtures/story-media', name)),
      contentType: mediaTypes[name.split('.').pop()!] || 'text/plain'
    });
  });
  for (const provider of ['https://datawrapper.dwcdn.net/**', 'https://flo.uri.sh/**', 'https://www.openstreetmap.org/**', 'https://www.google.com/**', 'https://maps.google.com/**']) {
    await page.route(provider, (route) => {
      requested.push(route.request().url());
      return route.fulfill({ contentType: 'text/html', body: '<!doctype html><html><body>Controlled graphic</body></html>' });
    });
  }
  return requested;
}

/**
 * Linux CI reserves a 15px right-hand gutter (`html { scrollbar-gutter: stable }`)
 * while drawing no scrollbar, so the layout viewport is 15px narrower than
 * `documentElement.clientWidth`. Reproduce exactly that on any platform.
 */
export async function reserveScrollbarGutter(page: Page) {
  await page.addStyleTag({ content: 'html{box-sizing:border-box;padding-right:15px}' });
}

/** A drawn classic 15px scrollbar. Needs a browser launched without `--hide-scrollbars`. */
export async function classicScrollbar(page: Page) {
  await page.addStyleTag({ content: 'html{overflow-y:scroll}html::-webkit-scrollbar{width:15px}html::-webkit-scrollbar-thumb{background:#888}' });
}

/** Load a story page with every image decoded so geometry is final. */
export async function openStory(page: Page, url = article) {
  await page.goto(url);
  await page.locator('.article-body img').evaluateAll((images) => images.forEach((image) => ((image as HTMLImageElement).loading = 'eager')));
  await page.waitForFunction(() => Array.from(document.querySelectorAll<HTMLImageElement>('.article-body img')).every((image) => image.complete && image.naturalWidth > 0));
}

/**
 * The article canvas the CSS lays blocks out in: the content box of the
 * `byline-content` container (the article shell), not the browser viewport.
 * `100cqw` in the width contract resolves against exactly this box.
 */
export function articleCanvas(page: Page) {
  return page.evaluate(() => {
    const shell = document.querySelector<HTMLElement>('main.article-shell')!;
    const style = getComputedStyle(shell);
    const rect = shell.getBoundingClientRect();
    const paddingLeft = parseFloat(style.paddingLeft);
    const paddingRight = parseFloat(style.paddingRight);
    const width = rect.width - paddingLeft - paddingRight - parseFloat(style.borderLeftWidth) - parseFloat(style.borderRightWidth);
    const left = rect.left + paddingLeft + parseFloat(style.borderLeftWidth);
    return {
      shell: { left: rect.left, right: rect.right, width: rect.width },
      body: document.body.getBoundingClientRect().toJSON() as { left: number; right: number },
      width,
      left,
      right: left + width,
      center: left + width / 2,
      viewport: document.documentElement.clientWidth,
      overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1
    };
  });
}
